plain=[{'poem_id': 430, 'rationale': 'The closing disclosure of the mother’s death changes the whole sequence of ordinary events. Preserve that reading discovery without an illustration announcing grief.', 'status': 'pending'}, {'poem_id': 436, 'rationale': 'Hunger, ritual, earth and bodily dissolution remain a complex first-person argument. Avoid a fabricated starving person or a decorative religious scene.', 'status': 'pending'}, {'poem_id': 439, 'rationale': 'The speaker explicitly challenges what observers think they can see. A text-led opening respects the unseen pain instead of inventing an injured body or misleading smile.', 'status': 'pending'}]
